.brand {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-weight: 600;
  font-size: 1rem;
  color: var(--text);
}

.brand-mark {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, #2563eb, #7c3aed);
}

.breadcrumb {
  font-size: 0.875rem;
  color: var(--muted);
}
.breadcrumb a {
  color: var(--muted);
  text-decoration: none;
}
.breadcrumb a:hover {
  color: var(--text);
  text-decoration: underline;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.image-frame {
  background: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.meta {
  padding: 1.25rem 1.5rem;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
  border-bottom: 1px solid var(--border);
}

.meta h1 {
  font-size: 1.125rem;
  margin: 0 0 0.25rem;
  font-weight: 600;
}

.meta p {
  margin: 0;
  color: var(--muted);
  font-size: 0.875rem;
}

.actions {
  display: flex;
  gap: 0.625rem;
  padding: 1rem 1.5rem;
  background: #fafafa;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font: inherit;
  font-weight: 500;
  font-size: 0.9375rem;
  padding: 0.55rem 1rem;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease, box-shadow 120ms ease;
  background: transparent;
  color: var(--text);
  line-height: 1.2;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-secondary {
  background: var(--surface);
  border-color: var(--border);
  color: var(--text);
  box-shadow: var(--shadow-sm);
}
.btn-secondary:hover:not(:disabled) {
  background: #f1f5f9;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

.btn-ghost {
  background: transparent;
  color: var(--muted);
}
.btn-ghost:hover:not(:disabled) {
  color: var(--text);
  background: #f1f5f9;
}

.icon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

/* Modal */
.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 100;
  animation: fadeIn 150ms ease-out;
}

.dialog {
  background: var(--surface);
  border-radius: var(--radius);
  width: 100%;
  max-width: 440px;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  animation: scaleIn 160ms cubic-bezier(0.2, 0.8, 0.4, 1);
}

.dialog-header {
  display: flex;
  align-items: flex-start;
  gap: 0.875rem;
  padding: 1.5rem 1.5rem 0.5rem;
}

.dialog-icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #fee2e2;
  color: var(--danger);
  display: flex;
  align-items: center;
  justify-content: center;
}

.dialog-title {
  margin: 0.25rem 0 0;
  font-size: 1.0625rem;
  font-weight: 600;
}

.dialog-body {
  padding: 0.5rem 1.5rem 1.25rem;
  color: var(--muted);
  font-size: 0.9375rem;
}

.dialog-body p {
  margin: 0;
}

.dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  padding: 1rem 1.5rem 1.25rem;
  background: #fafafa;
  border-top: 1px solid var(--border);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes scaleIn {
  from { opacity: 0; transform: translateY(4px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog { animation: none; }
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.toast {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  background: var(--text);
  color: #fff;
  padding: 0.75rem 1.125rem;
  border-radius: 8px;
  box-shadow: var(--shadow-md);
  font-size: 0.9375rem;
  z-index: 200;
  animation: fadeIn 150ms ease-out;
}

.empty-state {
  padding: 3rem 1.5rem;
  text-align: center;
  color: var(--muted);
}
.empty-state h2 {
  color: var(--text);
  margin: 0 0 0.5rem;
  font-size: 1.0625rem;
}
.empty-state p { margin: 0; font-size: 0.9375rem; }
